  ('saemling', 'Sämling', '', '', '', '', 'Sämling', '[{"kategorie": "", "text": "Sammelbezeichnung für verschiedene Neuzüchtungen von Rebsorten durch Kreuzungen"}, {"kategorie": "", "text": "Der Begriff \"Sämling\" deutet darauf hin, dass diese neuen Sorten aus der Kreuzung von verschiedenen Elternreben entstanden sind. Die genaue Bezeichnung eines Sämlings wird normalerweise durch eine Nummer oder einen spezifischen Namen ergänzt, die den Züchtungsprozess und die Herkunft der Sorte kennzeichnen (z.B. [[Müller-Thurgau]] = Kreuzung aus Riesling und Gutedel)."}]'::jsonb, ''),
  ('riisling', 'Riisling', '', '', '', '', 'Riesling', '[{"kategorie": "", "text": "trockener bis halbtrockener (bis hin zu lieblicher) Weißwein mit einer klaren, hellgelben Farbe und Aromen von Zitrusfrüchten wie Limette, Zitrone und Grapefruit, begleitet von blumigen Noten wie Akazien und Jasmin)"}, {"kategorie": "", "text": "Riesling-Traube (ursprünglich aus Deutschland,  eine der bekanntesten und am meisten geschätzten weißen Rebsorten weltweit - klein bis mittelgroß, oval oder länglich mit einer dünnen Schale, bekannt für ihre hohe Säure)."}]'::jsonb, ''),
