  ('schmiaranski', 'Schmiaranski', '', '', '', 'Grundwortschatz Wienerisch', 'Schmieranski', '[{"kategorie": "wörtlich", "text": "\"Schmierfink\" (vom mittelhochdeutschen \"smirwen\"=\"schmieren\")"}, {"kategorie": "allg.", "text": "\"Schmierheini\" (jemand, der \"schmiert\", d.h. unsauber bzw. unleserlich schreibt), \"Kritzelkönig\", \"Sauklaue\""}, {"kategorie": "Journalistenjargon", "text": "Boulevardjournalist, Klatschreporter, \"Schmierfink\""}]'::jsonb, 'Da Schmiaranski aus unsan Büro hod wieda zuagschloong - den sei Schrift kaunn  nuara Kryptolog entziffan!'),
  ('schmiiablaadl', 'Schmiiablaadl', 'das', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Schmierblattl', '[{"kategorie": "wörtlich", "text": "\"Schmierblatt\" (vom mittelhochdeutschen \"smirwen\"=\"schmieren\" und \"blat\"=\"Blatt\")"}, {"kategorie": "allg.", "text": "Schmierzettel, Schmierblatt, Kritzelblatt, Schreibfetzen, Notizzettel"}, {"kategorie": "Pressejargon", "text": "Boulevardzeitung, Sensationsblatt, Klatschblatt, [[Schundblaadl]], [[Rewoiwablaadl]], [[Kaasblaadl]], [[Drecksblaadl]]"}, {"kategorie": "Kartenspielerjargon", "text": "\"schmiertaugliches Kartenblatt\" (d.h. Spielkarte hohen Werts, mit der man zwar selbst keinen Stich machen kann, die sich aber vortrefflich zum [[Schmieren]] [als fette Zugabe zum Stich des Partners] eignet)"}]'::jsonb, 'Iwaroi im Büro liing Schmiiablaadln umanaund - kaa Wunda, dass I nix find!'),
